# print profiles for lowest 5 days
byd=collections.defaultdict(list)
for t,v in rows: byd[t.date()].append((t,v))
mins=sorted((min(v for t,v in vs),d) for d,vs in byd.items())
for mn,d in mins[:8]:
    print('\nDATE',d,'day min',mn,'max',max(v for t,v in byd[d]))
    for t,v in byd[d]:
        if 9<=t.hour<=17:
            print(t.strftime('%H:%M'),v,end='; ')
    print()
# flatlines: runs of same value
runs=[]; start=0
for i in range(1,len(rows)):
    if rows[i][1]!=rows[i-1][1]:
        if i-start>=8: runs.append((i-start,rows[start][0],rows[start][1],rows[i-1][0]))
        start=i
if len(rows)-start>=8: runs.append((len(rows)-start,rows[start][0],rows[start][1],rows[-1][0]))
print('\nflat runs >=8 intervals:',len(runs))
for r in sorted(runs,reverse=True)[:20]: print(r)
# biggest 15-min drops
drops=[]
for i in range(1,len(rows)):
    dv=rows[i][1]-rows[i-1][1]
    if abs(dv)>1500: drops.append((abs(dv),dv,rows[i-1][0],rows[i-1][1],rows[i][0],rows[i][1]))
print('\nbig jumps >1500:',len(drops))
for x in sorted(drops,reverse=True)[:20]: print(x)
