exit_code=0
#!/usr/bin/env python3
"""Check the Bramwick Commons memo against the source records, the requirements table,
and the SRP-3 documentation rules."""
import csv, json, os, re, subprocess, sys
from datetime import date
from docx import Document
import openpyxl

ROOT='/filesystem'
MEMO=os.path.join(ROOT,'Bramwick_Commons_Screen_Memo.docx')
REQ='/tmp/ahpele/requirements.csv'
REJ='/tmp/ahpele/rejected.csv'
AMI=os.path.join(ROOT,'Studies/ALN-214_AMI_Interval_Load_Export.xlsx')
sys.path.insert(0,'/tmp/ahpele')
from calc import load_ami, compute

errors=[]; notes=[]
def fail(msg): errors.append(msg)
def ok(msg): notes.append(msg)

# 1. document opens and has text
if not os.path.exists(MEMO):
    fail('memo file missing')
    print('FAILED'); sys.exit(1)
doc=Document(MEMO)
text='\n'.join(p.text for p in doc.paragraphs)
for t in doc.tables:
    for row in t.rows:
        for cell in row.cells:
            text+='\n'+cell.text
words=len(text.split())
if words<1000: fail(f'memo only {words} words')
ok(f'memo opens: {words} words, {len(doc.tables)} tables')

# 2. required content tokens
must=['Bramwick Commons Solar LLC','ALN-214','1.8 MW','1,800 kW','2,400 kW','2.4 MW',
      '2,418 kW','1,985 kW','1,100 kW','2025-02-12 11:30','2025-01-25 10:00',
      '2025-03-23 03:45','2025-01-19 07:30','07/01/2024','06/30/2025','8,760','35,040',
      'PASS','advance without a study agreement','IS-BRAM-2025-06-25','SUPERSEDED',
      'SRP-3 Rev 3','10:00–16:00','25.0%','75.0%','600 kW']
for m in must:
    if m not in text:
        fail(f'required token missing: {m!r}')
ok('required content tokens present')

# 3. recompute AMI values from the workbook and compare
stats=compute(load_ami(AMI))
checks={
 'records':35040,'days':365,'daytime_records':8760,'day_min_kw':2400,
 'day_min_clean_kw':2418,'abs_min_kw':1100,'abs_min_clean_kw':1985}
for k,v in checks.items():
    if stats[k]!=v:
        fail(f'AMI {k}={stats[k]} expected {v}')
if stats['cadence_minutes']!=[15.0]: fail(f"cadence {stats['cadence_minutes']}")
if stats['first']!='2024-07-01T00:00:00' or stats['last']!='2025-06-30T23:45:00':
    fail(f"data window {stats['first']}..{stats['last']}")
ok('AMI recomputation matches the memo: 35,040 records; 8,760 daytime; 2,400 kW; 2,418 / 1,985 clean values')

# 4. Screen D decision arithmetic
if not (1800 <= stats['day_min_kw']): fail('1,800 kW does not pass 2,400 kW')
if not (1800 <= stats['day_min_clean_kw']): fail('1,800 kW does not pass clean 2,418 kW')
util=1800/stats['day_min_kw']*100
if abs(util-75.0)>0.01: fail(f'utilisation {util}')
ok('Screen D arithmetic: 1,800 <= 2,400; utilisation 75.0%; margin 600 kW')

# 5. all screens A-E present and marked pass
for s in ['A — Aggregate DER penetration','B — Voltage regulation and flicker',
          'C — Short-circuit contribution','D — 100%-of-minimum-load','E — Reverse power at substation']:
    if s not in text: fail(f'screen missing: {s}')
if text.count('PASS')<5: fail('fewer than five PASS calls')
ok('Screens A-E all present with PASS determinations')

# 6. disposition language
if 'advance without a study agreement' not in text and 'advance without study agreement' not in text:
    fail('disposition does not say advance without study agreement')
if 'advance without study agreement' not in text:
    fail('exact SRP-3 disposition phrase advance without study agreement is missing')
if 'Disposition: PASS' not in text:
    fail('disposition callout not marked PASS')
# no all-caps FAILED should appear in the current determination
if text.count('FAILED')!=0:
    fail(f"unexpected FAILED count {text.count('FAILED')}")
ok('disposition is PASS / advance without a study agreement; v1 failure only appears as quoted history')

# 6b. Screen A/B/C/E recomputation
from datetime import datetime as _dt
import math
hosting_mw=4.9; last_study=_dt(2023,12,1); asof=_dt(2025,7,14)
months=(asof.year-last_study.year)*12+(asof.month-last_study.month)
if months>24: fail(f'last study {months} months old > 24')
req_kw=1800; sens_kw=2350
if not (req_kw <= hosting_mw*1000): fail('Screen A primary aggregate exceeds 4.9 MW')
if not (sens_kw <= hosting_mw*1000): fail('Screen A sensitivity exceeds 4.9 MW')
if not (sens_kw <= stats['day_min_kw']): fail('Screen A/E sensitivity 2,350 kW exceeds 2,400 kW daytime minimum')
if not (req_kw <= stats['abs_min_clean_kw']): fail('Screen E aggregate exceeds 1,985 kW clean absolute minimum')
fault_mva=1.2*1.8
fault_a=fault_mva*1e6/(math.sqrt(3)*12.47e3)
if abs(fault_a-100.0)>1.0: fail(f'fault current {fault_a:.1f} A not ~100 A')
if abs(req_kw/(hosting_mw*1000)*100-36.7347)>0.01: fail('Screen B/A utilisation not 36.7%')
if abs(req_kw/stats['abs_min_clean_kw']*100-90.680)>0.01: fail('Screen E utilisation check')
for token in ['36.7%','48.0%','185 kW below the 1,985 kW night minimum','2,550 kW','19 months','2.16 MVA','4,900 kW','100 A','50 kW']:
    if token not in text:
        fail(f'expected supporting value missing: {token}')
if '185 kW below the 1,985 kW night minimum' not in text:
    fail('Screen E margin sentence does not say 185 kW below the 1,985 kW night minimum')
ok(f'Screens A/B/C/E arithmetic: 1,800/2,350 within 4,900; 2,350 within 2,400; 1,800 within 1,985; {fault_a:.1f} A fault increment; last study {months} months old')

# 7. queue / existing / hosting records
def sheet_rows(path, sheet, start):
    wb=openpyxl.load_workbook(path,data_only=True,read_only=True); ws=wb[sheet]
    return [r for r in ws.iter_rows(min_row=start,values_only=True) if r and any(v is not None for v in r)]
aq=sheet_rows(os.path.join(ROOT,'Queue/2025-07-14_Active_Queue_Report.xlsx'),'Active Queue',2)
oh=sheet_rows(os.path.join(ROOT,'Queue/2025-07-14_On_Hold_Queue_Report.xlsx'),'Holds',2)
ex=sheet_rows(os.path.join(ROOT,'Screening/Existing_DER_Register_Extract.xlsx'),'Register',17)
if len(aq)!=380: fail(f'active queue count {len(aq)}')
if len(oh)!=140: fail(f'on-hold count {len(oh)}')
if any(str(r[4]).strip()=='ALN-214' for r in aq if len(r)>4): fail('active queue has ALN-214 row')
if any('Bramwick' in str(r[1]) or 'Bramwick' in str(r[2]) for r in oh if len(r)>2): fail('on-hold has Bramwick row')
if any('Bramwick' in str(r[0]) or 'Bramwick' in str(r[1]) or 'Bramwick' in str(r[2]) for r in ex if len(r)>2): fail('existing register has Bramwick row')
lark=[r for r in ex if len(r)>2 and ('Larkspur' in str(r[0]) or 'Larkspur' in str(r[2]))]
if not lark or lark[0][3]!=550: fail('Larkspur 550 kW record not found')
# hosting
wb=openpyxl.load_workbook(os.path.join(ROOT,'Planning/Hosting_Capacity_Map_Export_2024-05-15.xlsx'),data_only=True,read_only=True)
ws=wb['Feeder Capacity']; h=None
for r in ws.iter_rows(min_row=5,values_only=True):
    if r[0]=='ALN-214' and isinstance(r[3],(int,float)): h=r
if not h or h[3]!=4.9: fail('ALN-214 4.9 MW hosting capacity not found')
ok('records: 380 active / 140 on-hold / 21 existing; no ALN-214 queue row; Larkspur 550 kW; HCM 4.9 MW')

# 8. requirements table integrity and candidate coverage
with open(REQ,newline='',encoding='utf-8') as fh:
    reqrows=list(csv.DictReader(fh))
expected_header=['req_id','requirement','limit_value','unit','source_document','clause','candidate_ids','applies_to','verification']
if list(reqrows[0].keys())!=expected_header: fail('requirements header mismatch')
if len(reqrows)<40: fail(f'only {len(reqrows)} requirements')
for i,r in enumerate(reqrows,2):
    for k in expected_header:
        if not str(r.get(k,'')).strip(): fail(f'requirements row {i} empty {k}')
    src=r['source_document']
    if not os.path.exists(os.path.join(ROOT,src)): fail(f'requirements row {i} source not found: {src}')
ok(f'requirements table: {len(reqrows)} rows, all fields populated, all source files exist')

# 9. reqscan register and coverage
p=subprocess.run(['python3','/tmp/ahpele/bin/ahpele_reqscan.py','--register',REQ,'--limit','100'],capture_output=True,text=True)
line=p.stdout.splitlines()[0] if p.stdout else ''
m=re.search(r'REGISTER rows=(\d+) notfound=(\d+) unmatched=(\d+) multi=(\d+)',line)
if not m: fail('reqscan register did not return REGISTER line: '+line)
else:
    if int(m.group(2)) or int(m.group(3)) or int(m.group(4)):
        fail('reqscan register failures: '+line)
    ok('reqscan register: '+line)
p=subprocess.run(['python3','/tmp/ahpele/bin/ahpele_reqscan.py','--check','--limit','100'],capture_output=True,text=True)
if '0 not reviewed yet' not in p.stdout:
    fail('reqscan coverage not complete: '+p.stdout.splitlines()[0] if p.stdout else 'no output')
else:
    ok('reqscan coverage: 54/54 strong project candidates reviewed')

# 10. date arithmetic
if date(2025,7,14).weekday()!=0: fail('07/14/2025 is not Monday')
d=date(2025,7,14); n=0
while n<5:
    d=date.fromordinal(d.toordinal()+1)
    if d.weekday()<5: n+=1
if d!=date(2025,7,21): fail(f'5 business days after 07/14 is {d}')
if '07/21/2025' not in text: fail('memo does not state 07/21/2025 filing deadline')
ok('date arithmetic: 07/14/2025 + 5 business days = 07/21/2025')

# 11. format check
p=subprocess.run(['python3','/tmp/ahpele/bin/ahpele_check.py',MEMO],capture_output=True,text=True)
if p.returncode!=0: fail('ahpele_check failed: '+p.stdout+p.stderr)
else: ok('ahpele_check: no problems')

print('CHECKS RUN:', len(notes))
for n in notes: print('  ok  ',n)
if errors:
    print('\nFAILURES:',len(errors))
    for e in errors: print('  FAIL',e)
    sys.exit(1)
print('\nALL CHECKS PASSED')

