#!/usr/bin/env python3
"""Summarise DER Program records relevant to Bramwick / ALN-214 as of 07/14/2025."""
import json, openpyxl, re
from datetime import datetime

def active_queue(path='/filesystem/Queue/2025-07-14_Active_Queue_Report.xlsx'):
    wb=openpyxl.load_workbook(path,data_only=True,read_only=True)
    ws=wb['Active Queue']
    rows=[]
    for r in ws.iter_rows(min_row=2,values_only=True):
        if r[0]: rows.append({'id':r[0],'customer':r[1],'site':r[2],'capacity':r[3],'feeder':r[4],'queue_date':r[5],'status':r[6]})
